INSERT INTO `mkt_ai_generation_task` (`id`, `task_no`, `user_id`, `scene`, `quota_type`, `prompt`, `input_json`, `output_text`, `output_json`, `ai_config_id`, `provider_type`, `model`, `status`, `tokens_prompt`, `tokens_completion`, `tokens_total`, `quota_cost`, `quota_log_ids_json`, `error_message`, `started_time`, `finished_time`, `ip`, `user_agent`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (26, 'AIT20260527194517214456', 1, 'recommend_post', 'generation', '请生成一条小红书求推荐帖。需求：想找适合朋友生日聚餐的餐厅，环境不要太吵，菜品稳定一点，适合拍照聊天。城市/商圈：龙湖区黄山路71号正迪科技大厦一楼附近，距离星湖商业城步行1.3km。预算：人均150以内。口吻：生日聚餐求助。\n\n必须只输出一个合法 JSON 对象，不要输出 Markdown、代码块、解释文字或多余前后缀。\nJSON 结构必须完全如下：\n{\n  \"title\": \"一条最适合直接展示的中文标题，30字以内，不要包含标题候选、正文等字段名\",\n  \"content\": \"一条完整的小红书求推荐正文，口语化、真实、有求助感，正文里不要包含标题候选列表\"\n}\n\n字段要求：\n1. title 只能是一条标题，不能是数组，不能写“标题候选：”。\n2. content 只能是正文，不能混入标题候选、JSON 以外说明或平台无关内容。\n3. JSON 字符串内如需换行请使用 \\n。', '{\"scene\": \"recommend_post\", \"prompt\": \"请生成一条小红书求推荐帖。需求：想找适合朋友生日聚餐的餐厅，环境不要太吵，菜品稳定一点，适合拍照聊天。城市/商圈：龙湖区黄山路71号正迪科技大厦一楼附近，距离星湖商业城步行1.3km。预算：人均150以内。口吻：生日聚餐求助。\\n\\n必须只输出一个合法 JSON 对象，不要输出 Markdown、代码块、解释文字或多余前后缀。\\nJSON 结构必须完全如下：\\n{\\n  \\\"title\\\": \\\"一条最适合直接展示的中文标题，30字以内，不要包含标题候选、正文等字段名\\\",\\n  \\\"content\\\": \\\"一条完整的小红书求推荐正文，口语化、真实、有求助感，正文里不要包含标题候选列表\\\"\\n}\\n\\n字段要求：\\n1. title 只能是一条标题，不能是数组，不能写“标题候选：”。\\n2. content 只能是正文，不能混入标题候选、JSON 以外说明或平台无关内容。\\n3. JSON 字符串内如需换行请使用 \\\\n。\", \"options\": null, \"quota_type\": \"generation\", \"template_id\": 14, \"render_input\": {\"tone\": \"生日聚餐求助\", \"budget\": \"人均150以内\", \"location\": \"龙湖区黄山路71号正迪科技大厦一楼附近，距离星湖商业城步行1.3km\", \"request_detail\": \"想找适合朋友生日聚餐的餐厅，环境不要太吵，菜品稳定一点，适合拍照聊天\"}, \"system_prompt\": \"你是小红书求推荐帖文案助手。必须严格输出可被 JSON.parse 解析的 JSON 对象，只允许包含 title 和 content 两个字符串字段，不要输出 Markdown、代码块、解释文字或标题候选列表。\", \"account_profile\": null}', NULL, NULL, 2, 'generic', 'gpt-5.5', 3, 0, 0, 0, 10, NULL, '请先开通会员或购买积分包', NULL, '2026-05-27 19:45:17', NULL, NULL, NULL, 1, 1, '2026-05-27 19:45:17', '20