-- ----------------------------
-- Table structure for mkt_content
-- ----------------------------
DROP TABLE IF EXISTS `mkt_content`;
CREATE TABLE `mkt_content` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `template_id` int unsigned DEFAULT NULL COMMENT '提示词模板ID',
  `task_no` varchar(50) DEFAULT NULL COMMENT 'AI任务编号',
  `title` varchar(200) NOT NULL COMMENT '内容标题',
  `content` mediumtext COMMENT '正文内容',
  `tags_json` json DEFAULT NULL COMMENT '标签JSON',
  `cover_text` varchar(255) DEFAULT NULL COMMENT '封面文案',
  `image_prompt` mediumtext COMMENT '图片提示词',
  `image_url` varchar(1000) DEFAULT NULL COMMENT '图片地址',
  `input_json` json DEFAULT NULL COMMENT '生成输入JSON',
  `output_json` json DEFAULT NULL COMMENT '生成输出JSON',
  `source_type` varchar(50) DEFAULT NULL COMMENT '来源类型',
  `source_id` varchar(64) DEFAULT NULL COMMENT '来源ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1草稿 2待审核 3已通过 4已归档',
  `version` int unsigned NOT NULL DEFAULT '1' COMMENT '版本号',
  `exported_flag` tinyint NOT NULL DEFAULT '2' COMMENT '是否已导出 1是 2否',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`),
  KEY `idx_template_id` (`template_id`),
  KEY `idx_task_no` (`task_no`),
  KEY `idx_source` (`source_type`,`source_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='内容作品库';

-- ----------------------------
-- Records of mkt_content
-- ----------------------------
