INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (1, 111, 14, 'AIT20260527121143365898', '龙湖区朋友生日聚餐求推荐！人均150内🙏', '姐妹们求助一下！！\n\n朋友快生日了，想找一家适合聚餐的餐厅，位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/打车方便一点就行。\n\n预算希望控制在人均150以内，不想太贵，但也想吃得有点特色，环境不要太吵，适合朋友一起聊天拍照，最好菜品稳定一点，不踩雷。\n\n我们几个都比较能接受火锅、潮汕菜、卤味这类，最近有刷到卤水火锅，好像有非遗卤水锅底、狮头鹅、鲜切牛肉、卤味拼盘这些，感觉还挺适合外地朋友体验潮汕味道的，但不知道生日聚餐氛围怎么样。\n\n有没有本地姐妹吃过附近的店？  \n求推荐适合生日聚餐、服务和出品都还不错的餐厅！最好能说说人均、必点菜、需不需要提前订位～谢谢大家！！', '[]', NULL, NULL, NULL, '{\"tone\": \"真实求助\", \"budget\": \"人均150以内\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"想找适合朋友生日聚餐的餐厅\"}', '{\"task_no\": \"AIT20260527121143365898\", \"output_json\": \"{\\\"content\\\": \\\"标题候选：\\\\n1. 龙湖区朋友生日聚餐求推荐！人均150内🙏\\\\n2. 星湖商业城附近有没有适合生日聚餐的店？\\\\n3. 黄山路附近生日饭去哪吃？求本地人推荐！\\\\n\\\\n正文：\\\\n姐妹们求助一下！！\\\\n\\\\n朋友快生日了，想找一家适合聚餐的餐厅，位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/打车方便一点就行。\\\\n\\\\n预算希望控制在人均150以内，不想太贵，但也想吃得有点特色，环境不要太吵，适合朋友一起聊天拍照，最好菜品稳定一点，不踩雷。\\\\n\\\\n我们几个都比较能接受火锅、潮汕菜、卤味这类，最近有刷到卤水火锅，好像有非遗卤水锅底、狮头鹅、鲜切牛肉、卤味拼盘这些，感觉还挺适合外地朋友体验潮汕味道的，但不知道生日聚餐氛围怎么样。\\\\n\\\\n有没有本地姐妹吃过附近的店？  \\\\n求推荐适合生日聚餐、服务和出品都还不错的餐厅！最好能说说人均、必点菜、需不需要提前订位～谢谢大家！！\\\"}\", \"output_text\": \"标题候选：\\n1. 龙湖区朋友生日聚餐求推荐！人均150内🙏\\n2. 星湖商业城附近有没有适合生日聚餐的店？\\n3. 黄山路附近生日饭去哪吃？求本地人推荐！\\n\\n正文：\\n姐妹们求助一下！！\\n\\n朋友快生日了，想找一家适合聚餐的餐厅，位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/打车方便一点就行。\\n\\n预算希望控制在人均150以内，不想太贵，但也想吃得有点特色，环境不要太吵，适合朋友一起聊天拍照，最好菜品稳定一点，不踩雷。\\n\\n我们几个都比较能接受火锅、潮汕菜、卤味这类，最近有刷到卤水火锅，好像有非遗卤水锅底、狮头鹅、鲜切牛肉、卤味拼盘这些，感觉还挺适合外地朋友体验潮汕味道的，但不知道生日聚餐氛围怎么样。\\n\\n有没有本地姐妹吃过附近的店？  \\n求推荐适合生日聚餐、服务和出品都还不错的餐厅！最好能说说人均、必点菜、需不需要提前订位～谢谢大家！！\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, 111, '2026-05-27 12:11:57', '2026-05-27 12:47:06', NULL);
