INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (3, 111, 14, 'AIT20260527125220414277', '龙湖区约会火锅求推荐！', '想问问汕头本地朋友～龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城步行能到的范围，有没有适合两个人约会吃饭的火锅/潮汕菜推荐呀？\n\n预算大概人均120-180，希望环境舒服一点、聊天不吵，最好不要排队太久。我们比较想吃有潮汕特色的，比如卤水火锅、鲜切牛肉、卤味拼盘、粿条海鲜这些都可以。\n\n看到附近有家潮卤道非遗卤水火锅，好像是卤水锅底和狮头鹅比较有特色，不知道适不适合情侣约会？味道、环境、等位情况怎么样？\n\n如果还有附近好吃不踩雷的店也求推荐！适合晚上去、两个人点菜不尴尬的那种～', '[]', NULL, NULL, NULL, '{\"tone\": \"约会探店求助\", \"budget\": \"人均120-180\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"想找适合两个人约会吃饭的火锅或潮汕菜，最好不要排队太久，环境舒服一点\"}', '{\"task_no\": \"AIT20260527125220414277\", \"output_json\": \"{\\\"content\\\": \\\"{\\\\\\\"title\\\\\\\":\\\\\\\"龙湖区约会火锅求推荐！\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"想问问汕头本地朋友～龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城步行能到的范围，有没有适合两个人约会吃饭的火锅/潮汕菜推荐呀？\\\\\\\\n\\\\\\\\n预算大概人均120-180，希望环境舒服一点、聊天不吵，最好不要排队太久。我们比较想吃有潮汕特色的，比如卤水火锅、鲜切牛肉、卤味拼盘、粿条海鲜这些都可以。\\\\\\\\n\\\\\\\\n看到附近有家潮卤道非遗卤水火锅，好像是卤水锅底和狮头鹅比较有特色，不知道适不适合情侣约会？味道、环境、等位情况怎么样？\\\\\\\\n\\\\\\\\n如果还有附近好吃不踩雷的店也求推荐！适合晚上去、两个人点菜不尴尬的那种～\\\\\\\"}\\\"}\", \"output_text\": \"{\\\"title\\\":\\\"龙湖区约会火锅求推荐！\\\",\\\"content\\\":\\\"想问问汕头本地朋友～龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城步行能到的范围，有没有适合两个人约会吃饭的火锅/潮汕菜推荐呀？\\\\n\\\\n预算大概人均120-180，希望环境舒服一点、聊天不吵，最好不要排队太久。我们比较想吃有潮汕特色的，比如卤水火锅、鲜切牛肉、卤味拼盘、粿条海鲜这些都可以。\\\\n\\\\n看到附近有家潮卤道非遗卤水火锅，好像是卤水锅底和狮头鹅比较有特色，不知道适不适合情侣约会？味道、环境、等位情况怎么样？\\\\n\\\\n如果还有附近好吃不踩雷的店也求推荐！适合晚上去、两个人点菜不尴尬的那种～\\\"}\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, NULL, '2026-05-27 12:52:30', NULL, NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (4, 111, 14, 'AIT20260527125304798243', '外地朋友来龙湖区吃啥不踩雷', '外地朋友第一次来汕头，想带他们吃一顿比较有本地特色的餐厅，求大家推荐🙏\n我们大概在龙湖区黄山路71号正迪科技大厦一楼附近，离星湖商业城步行大概1.3km，最好不要跑太远。\n预算人均100-160左右，想找那种有招牌菜、适合外地人体验潮汕味道、但又不会踩雷的店。\n目前看到附近有卤水火锅，说是有农家散养狮头鹅、非遗老卤锅底，还有鲜切牛肉、卤味拼盘、鹅血、粿条这些，感觉挺有特色的。想问问本地朋友这种适合带外地朋友去吗？\n主要诉求：环境别太乱、味道稳定、招牌菜值得点，最好能一顿吃到潮汕特色。大家有推荐的店或者必点菜吗？感谢！', '[]', NULL, NULL, NULL, '{\"tone\": \"外地游客求助\", \"budget\": \"人均100-160\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"外地朋友第一次来，想带他们吃有本地特色的餐厅，最好有招牌菜、不踩雷\"}', '{\"task_no\": \"AIT20260527125304798243\", \"output_json\": \"{\\\"content\\\": \\\"{\\\\\\\"title\\\\\\\":\\\\\\\"外地朋友来龙湖区吃啥不踩雷\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"外地朋友第一次来汕头，想带他们吃一顿比较有本地特色的餐厅，求大家推荐🙏\\\\\\\\n我们大概在龙湖区黄山路71号正迪科技大厦一楼附近，离星湖商业城步行大概1.3km，最好不要跑太远。\\\\\\\\n预算人均100-160左右，想找那种有招牌菜、适合外地人体验潮汕味道、但又不会踩雷的店。\\\\\\\\n目前看到附近有卤水火锅，说是有农家散养狮头鹅、非遗老卤锅底，还有鲜切牛肉、卤味拼盘、鹅血、粿条这些，感觉挺有特色的。想问问本地朋友这种适合带外地朋友去吗？\\\\\\\\n主要诉求：环境别太乱、味道稳定、招牌菜值得点，最好能一顿吃到潮汕特色。大家有推荐的店或者必点菜吗？感谢！\\\\\\\"}\\\"}\", \"output_text\": \"{\\\"title\\\":\\\"外地朋友来龙湖区吃啥不踩雷\\\",\\\"content\\\":\\\"外地朋友第一次来汕头，想带他们吃一顿比较有本地特色的餐厅，求大家推荐🙏\\\\n我们大概在龙湖区黄山路71号正迪科技大厦一楼附近，离星湖商业城步行大概1.3km，最好不要跑太远。\\\\n预算人均100-160左右，想找那种有招牌菜、适合外地人体验潮汕味道、但又不会踩雷的店。\\\\n目前看到附近有卤水火锅，说是有农家散养狮头鹅、非遗老卤锅底，还有鲜切牛肉、卤味拼盘、鹅血、粿条这些，感觉挺有特色的。想问问本地朋友这种适合带外地朋友去吗？\\\\n主要诉求：环境别太乱、味道稳定、招牌菜值得点，最好能一顿吃到潮汕特色。大家有推荐的店或者必点菜吗？感谢！\\\"}\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, NULL, '2026-05-27 12:53:14', NULL, NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (5, 111, 14, 'AIT20260527125339136497', '带长辈吃饭求推荐！龙湖区附近', '周末想带家里长辈一起吃顿饭，想找一家口味比较稳、环境干净舒服、停车也方便的餐厅～\n\n位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/开车都别太折腾长辈。\n\n预算大概人均100-150，希望菜品别太踩雷，最好是适合一家人慢慢吃的那种。火锅、潮汕特色、卤味牛肉之类都可以，只要味道稳定、服务别太乱就行。\n\n有姐妹去过这附近比较适合家庭聚餐的店吗？求真实推荐，最好说说停车方不方便、长辈能不能吃得惯～', '[]', NULL, NULL, NULL, '{\"tone\": \"家庭聚餐求助\", \"budget\": \"人均100-150\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"家里长辈一起吃饭，想找口味稳、环境干净、停车方便的餐厅\"}', '{\"task_no\": \"AIT20260527125339136497\", \"output_json\": \"{\\\"content\\\": \\\"{\\\\\\\"title\\\\\\\":\\\\\\\"带长辈吃饭求推荐！龙湖区附近\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"周末想带家里长辈一起吃顿饭，想找一家口味比较稳、环境干净舒服、停车也方便的餐厅～\\\\\\\\n\\\\\\\\n位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/开车都别太折腾长辈。\\\\\\\\n\\\\\\\\n预算大概人均100-150，希望菜品别太踩雷，最好是适合一家人慢慢吃的那种。火锅、潮汕特色、卤味牛肉之类都可以，只要味道稳定、服务别太乱就行。\\\\\\\\n\\\\\\\\n有姐妹去过这附近比较适合家庭聚餐的店吗？求真实推荐，最好说说停车方不方便、长辈能不能吃得惯～\\\\\\\"}\\\"}\", \"output_text\": \"{\\\"title\\\":\\\"带长辈吃饭求推荐！龙湖区附近\\\",\\\"content\\\":\\\"周末想带家里长辈一起吃顿饭，想找一家口味比较稳、环境干净舒服、停车也方便的餐厅～\\\\n\\\\n位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/开车都别太折腾长辈。\\\\n\\\\n预算大概人均100-150，希望菜品别太踩雷，最好是适合一家人慢慢吃的那种。火锅、潮汕特色、卤味牛肉之类都可以，只要味道稳定、服务别太乱就行。\\\\n\\\\n有姐妹去过这附近比较适合家庭聚餐的店吗？求真实推荐，最好说说停车方不方便、长辈能不能吃得惯～\\\"}\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, NULL, '2026-05-27 12:53:48', NULL, NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (6, 111, 14, 'AIT20260527125956165358', '龙湖区卤水火锅求避雷推荐', '最近小红书一直刷到卤水火锅，看得我好心动但又有点怕踩雷😭\n\n想问问大家，龙湖区黄山路71号正迪科技大厦一楼这附近，距星湖商业城步行大概1.3km，有没有真的值得去的卤水火锅？人均预算150左右可以接受，主要想吃到卤香够、食材新鲜、不会齁咸的那种。\n\n特别想求真实体验：\n1️⃣ 卤水锅底会不会越煮越咸？\n2️⃣ 狮头鹅/卤味拼盘值不值得点？\n3️⃣ 鲜切牛肉配卤水锅底好吃吗？\n4️⃣ 鹅血、粿条、海鲜、时蔬这些有没有必点或避雷？\n5️⃣ 游客去吃会不会被坑，分量和服务怎么样？\n\n如果有去过潮汕卤水火锅的姐妹/本地朋友，求推荐靠谱店和必点菜！也欢迎直接劝退，想听真实感受🙏', '[]', NULL, NULL, NULL, '{\"tone\": \"避雷求推荐\", \"budget\": \"人均150左右\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"最近刷到很多卤水火锅，不知道哪家真的好吃，想求真实体验和必点菜\"}', '{\"task_no\": \"AIT20260527125956165358\", \"output_json\": \"{\\\"content\\\": \\\"{\\\\\\\"title\\\\\\\":\\\\\\\"龙湖区卤水火锅求避雷推荐\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"最近小红书一直刷到卤水火锅，看得我好心动但又有点怕踩雷😭\\\\\\\\n\\\\\\\\n想问问大家，龙湖区黄山路71号正迪科技大厦一楼这附近，距星湖商业城步行大概1.3km，有没有真的值得去的卤水火锅？人均预算150左右可以接受，主要想吃到卤香够、食材新鲜、不会齁咸的那种。\\\\\\\\n\\\\\\\\n特别想求真实体验：\\\\\\\\n1️⃣ 卤水锅底会不会越煮越咸？\\\\\\\\n2️⃣ 狮头鹅/卤味拼盘值不值得点？\\\\\\\\n3️⃣ 鲜切牛肉配卤水锅底好吃吗？\\\\\\\\n4️⃣ 鹅血、粿条、海鲜、时蔬这些有没有必点或避雷？\\\\\\\\n5️⃣ 游客去吃会不会被坑，分量和服务怎么样？\\\\\\\\n\\\\\\\\n如果有去过潮汕卤水火锅的姐妹/本地朋友，求推荐靠谱店和必点菜！也欢迎直接劝退，想听真实感受🙏\\\\\\\"}\\\"}\", \"output_text\": \"{\\\"title\\\":\\\"龙湖区卤水火锅求避雷推荐\\\",\\\"content\\\":\\\"最近小红书一直刷到卤水火锅，看得我好心动但又有点怕踩雷😭\\\\n\\\\n想问问大家，龙湖区黄山路71号正迪科技大厦一楼这附近，距星湖商业城步行大概1.3km，有没有真的值得去的卤水火锅？人均预算150左右可以接受，主要想吃到卤香够、食材新鲜、不会齁咸的那种。\\\\n\\\\n特别想求真实体验：\\\\n1️⃣ 卤水锅底会不会越煮越咸？\\\\n2️⃣ 狮头鹅/卤味拼盘值不值得点？\\\\n3️⃣ 鲜切牛肉配卤水锅底好吃吗？\\\\n4️⃣ 鹅血、粿条、海鲜、时蔬这些有没有必点或避雷？\\\\n5️⃣ 游客去吃会不会被坑，分量和服务怎么样？\\\\n\\\\n如果有去过潮汕卤水火锅的姐妹/本地朋友，求推荐靠谱店和必点菜！也欢迎直接劝退，想听真实感受🙏\\\"}\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, NULL, '2026-05-27 13:00:07', NULL, NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (7, 111, 14, 'AIT20260527130223501405', '带长辈在龙湖区吃饭求推荐', '周末想带家里长辈一起吃顿饭，求大家推荐一下龙湖区黄山路71号正迪科技大厦一楼附近的餐厅～最好离星湖商业城别太远，步行/开车都方便。\n\n预算大概人均100-150，主要想找口味比较稳、环境干净舒服、停车方便的店。长辈不太能接受太吵太重口，菜品最好有潮汕特色，像卤味、火锅、牛肉、粿条、时蔬这类都可以，吃起来踏实一点。\n\n有没有本地朋友吃过觉得适合家庭聚餐的？希望服务也不要太拉胯，座位宽敞一点更好。求真实推荐，感谢大家！', '[]', NULL, NULL, NULL, '{\"tone\": \"家庭聚餐求助\", \"budget\": \"人均100-150\", \"location\": \"龙湖区黄山路 71 号正迪科技大厦一楼，距星湖商业城步行 1.3km\", \"request_detail\": \"家里长辈一起吃饭，想找口味稳、环境干净、停车方便的餐厅\"}', '{\"task_no\": \"AIT20260527130223501405\", \"output_json\": \"{\\\"content\\\": \\\"{\\\\\\\"title\\\\\\\":\\\\\\\"带长辈在龙湖区吃饭求推荐\\\\\\\",\\\\\\\"content\\\\\\\":\\\\\\\"周末想带家里长辈一起吃顿饭，求大家推荐一下龙湖区黄山路71号正迪科技大厦一楼附近的餐厅～最好离星湖商业城别太远，步行/开车都方便。\\\\\\\\n\\\\\\\\n预算大概人均100-150，主要想找口味比较稳、环境干净舒服、停车方便的店。长辈不太能接受太吵太重口，菜品最好有潮汕特色，像卤味、火锅、牛肉、粿条、时蔬这类都可以，吃起来踏实一点。\\\\\\\\n\\\\\\\\n有没有本地朋友吃过觉得适合家庭聚餐的？希望服务也不要太拉胯，座位宽敞一点更好。求真实推荐，感谢大家！\\\\\\\"}\\\"}\", \"output_text\": \"{\\\"title\\\":\\\"带长辈在龙湖区吃饭求推荐\\\",\\\"content\\\":\\\"周末想带家里长辈一起吃顿饭，求大家推荐一下龙湖区黄山路71号正迪科技大厦一楼附近的餐厅～最好离星湖商业城别太远，步行/开车都方便。\\\\n\\\\n预算大概人均100-150，主要想找口味比较稳、环境干净舒服、停车方便的店。长辈不太能接受太吵太重口，菜品最好有潮汕特色，像卤味、火锅、牛肉、粿条、时蔬这类都可以，吃起来踏实一点。\\\\n\\\\n有没有本地朋友吃过觉得适合家庭聚餐的？希望服务也不要太拉胯，座位宽敞一点更好。求真实推荐，感谢大家！\\\"}\"}', 'recommend_post', '14', 1, 1, 2, NULL, 111, NULL, '2026-05-27 13:02:32', NULL, NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (8, 111, 17, 'AIT20260528011331531276', '一张适合火锅店上新的营销图片', '![image](http://127.0.0.1:8787/storage/20260528/28098506ff7579c48dcf7646a4806763.png)', '[]', NULL, '一张适合火锅店上新的营销图片。图片数量：2。图片比例：4:5。风格：餐饮海报。要求画面干净、主体突出、适合社媒传播。', 'http://127.0.0.1:8787/storage/20260528/28098506ff7579c48dcf7646a4806763.png', '{\"style\": \"餐饮海报\", \"prompt\": \"一张适合火锅店上新的营销图片\", \"image_count\": \"2\", \"aspect_ratio\": \"4:5\"}', '{\"task_no\": \"AIT20260528011331531276\", \"output_json\": \"{\\\"content\\\": \\\"![image](http://127.0.0.1:8787/storage/20260528/28098506ff7579c48dcf7646a4806763.png)\\\"}\", \"output_text\": \"![image](http://127.0.0.1:8787/storage/20260528/28098506ff7579c48dcf7646a4806763.png)\"}', 'gpt_image2', '17', 1, 1, 2, NULL, 111, NULL, '2026-05-28 01:15:02', '2026-05-28 02:08:12', NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (9, 111, 17, 'AIT20260528014856217366', '一张适合火锅店上新的营销图片', '![image](http://127.0.0.1:8787/storage/20260528/34b326c959c659991f35c490d1d758a6.png)\n\n![image](http://127.0.0.1:8787/storage/20260528/51bdeec5769c332f2ea4c3af110cc207.png)', '[]', NULL, '一张适合火锅店上新的营销图片。图片数量：2。图片比例：16:9。风格：轻奢。要求画面干净、主体突出、适合社媒传播。', 'http://127.0.0.1:8787/storage/20260528/34b326c959c659991f35c490d1d758a6.png', '{\"style\": \"轻奢\", \"prompt\": \"一张适合火锅店上新的营销图片\", \"image_count\": \"2\", \"aspect_ratio\": \"16:9\"}', '{\"task_no\": \"AIT20260528014856217366\", \"output_json\": \"{\\\"content\\\": \\\"![image](http://127.0.0.1:8787/storage/20260528/34b326c959c659991f35c490d1d758a6.png)\\\\n\\\\n![image](http://127.0.0.1:8787/storage/20260528/51bdeec5769c332f2ea4c3af110cc207.png)\\\"}\", \"output_text\": \"![image](http://127.0.0.1:8787/storage/20260528/34b326c959c659991f35c490d1d758a6.png)\\n\\n![image](http://127.0.0.1:8787/storage/20260528/51bdeec5769c332f2ea4c3af110cc207.png)\"}', 'gpt_image2', '17', 1, 1, 2, NULL, 111, NULL, '2026-05-28 01:50:46', '2026-05-28 02:08:30', NULL);
INSERT INTO `mkt_content` (`id`, `user_id`, `template_id`, `task_no`, `title`, `content`, `tags_json`, `cover_text`, `image_prompt`, `image_url`, `input_json`, `output_json`, `source_type`, `source_id`, `status`, `version`, `exported_flag`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (10, 111, 7, 'AIT20260528031020328819', '一张干净通透的防晒产品生活方式图', '![image](http://127.0.0.1:8787/storage/20260528/1374bcf0f832886419fdeaea6b49e68b.png)', '[]', NULL, '一张干净通透的防晒产品生活方式图。图片比例：4:5。要求画面干净、主体明确、无多余文字、适合小红书封面或正文配图。', 'http://127.0.0.1:8787/storage/20260528/1374bcf0f832886419fdeaea6b49e68b.png', '{\"aspect_ratio\": \"4:5\", \"image_prompt\": \"一张干净通透的防晒产品生活方式图\"}', '{\"task_no\": \"AIT20260528031020328819\", \"output_json\": \"{\\\"content\\\": \\\"![image](http://127.0.0.1:8787/storage/20260528/1374bcf0f832886419fdeaea6b49e68b.png)\\\"}\", \"output_text\": \"![image](http://127.0.0.1:8787/storage/20260528/1374bcf0f832886419fdeaea6b49e68b.png)\"}', 'image_generate', '7', 1, 1, 2, NULL, 111, NULL, '2026-05-28 03:11:22', NULL, NULL);
COMMIT;

-- ----------------------------
-- Table structure for mkt_content_template
-- ----------------------------
DROP TABLE IF EXISTS `mkt_content_template`;
CREATE TABLE `mkt_content_template` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(100) NOT NULL COMMENT '模板名称',
  `code` varchar(80) NOT NULL COMMENT '模板编码',
  `template_type` varchar(50) NOT NULL COMMENT '模板类型 guide_image/image2/review_analysis',
  `category` varchar(50) DEFAULT NULL COMMENT '模板分类',
  `cover_url` varchar(1000) DEFAULT NULL COMMENT '封面图',
  `prompt_text` mediumtext COMMENT '模板提示词',
  `config_json` json DEFAULT NULL COMMENT '模板配置JSON',
  `sort` int NOT NULL DEFAULT '100' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1正常 2停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_type` (`template_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='内容模板库';

-- ----------------------------
-- Records of mkt_content_template
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mkt_credit_order
-- ----------------------------
DROP TABLE IF EXISTS `mkt_credit_order`;
CREATE TABLE `mkt_credit_order` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(50) NOT NULL COMMENT '积分订单号',
  `pay_order_no` varchar(50) DEFAULT NULL COMMENT '关联支付订单号',
  `user_id` int unsigned DEFAULT NULL COMMENT '系统用户ID',
  `package_id` int unsigned DEFAULT NULL COMMENT '积分包ID',
  `package_snapshot_json` json DEFAULT NULL COMMENT '积分包快照JSON',
  `order_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '订单金额',
  `pay_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '支付金额',
  `pay_method` varchar(60) DEFAULT NULL COMMENT '支付方式',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '订单状态 0待支付 1已支付 2已取消 3已关闭 4已退款',
  `paid_time` datetime DEFAULT NULL COMMENT '支付时间',
  `granted_time` datetime DEFAULT NULL COMMENT '积分发放时间',
  `expire_time` datetime DEFAULT NULL COMMENT '积分过期时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_pay_order_no` (`pay_order_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_package_id` (`package_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='积分订单表';

-- ----------------------------
-- Records of mkt_credit_order
-- ----------------------------
BEGIN;
INSERT INTO `mkt_credit_order` (`id`, `order_no`, `pay_order_no`, `user_id`, `package_id`, `package_snapshot_json`, `order_amount`, `pay_amount`, `pay_method`, `status`, `paid_time`, `granted_time`, `expire_time`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (1, 'CO202605262214443001', 'PAY202605262214446808', 111, 1, '{\"id\": 1, \"code\": \"content_100\", \"name\": \"内容加油包\", \"price\": \"9.90\", \"features\": [\"一次性增加100内容积分\", \"长期有效\"], \"image_quota\": 0, \"validity_days\": 0, \"generation_quota\": 100}', 9.90, 9.90, 'wechat', 0, NULL, NULL, NULL, '用户中心下单', 111, NULL, '2026-05-26 22:14:44', NULL, NULL);
COMMIT;

-- ----------------------------
-- Table structure for mkt_credit_package
-- ----------------------------
DROP TABLE IF EXISTS `mkt_credit_package`;
CREATE TABLE `mkt_credit_package` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(100) NOT NULL COMMENT '积分包名称',
  `code` varchar(50) NOT NULL COMMENT '积分包编码',
  `generation_quota` int unsigned NOT NULL DEFAULT '0' COMMENT '内容积分',
  `image_quota` int unsigned NOT NULL DEFAULT '0' COMMENT '图片积分',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '售价',
  `original_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '原价',
  `validity_days` int unsigned NOT NULL DEFAULT '0' COMMENT '有效天数 0永久',
  `features_json` json DEFAULT NULL COMMENT '权益配置JSON',
  `sort` int NOT NULL DEFAULT '100' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1正常 2停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='积分包表';

-- ----------------------------
-- Records of mkt_credit_package
-- ----------------------------
BEGIN;
INSERT INTO `mkt_credit_package` (`id`, `name`, `code`, `generation_quota`, `image_quota`, `price`, `original_price`, `validity_days`, `features_json`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (1, '内容加油包', 'content_100', 100, 0, 9.90, 12.90, 0, '[\"一次性增加100内容积分\", \"长期有效\"]', 10, 1, '模拟积分包，可按实际业务调整', 1, NULL, '2026-05-26 18:18:33', NULL, NULL);
INSERT INTO `mkt_credit_package` (`id`, `name`, `code`, `generation_quota`, `image_quota`, `price`, `original_price`, `validity_days`, `features_json`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (2, '图片加油包', 'image_30', 0, 30, 12.90, 16.90, 0, '[\"一次性增加30图片积分\", \"长期有效\"]', 20, 1, '模拟积分包，可按实际业务调整', 1, NULL, '2026-05-26 18:18:33', NULL, NULL);
