-- ----------------------------
-- Table structure for mkt_export_batch
-- ----------------------------
DROP TABLE IF EXISTS `mkt_export_batch`;
CREATE TABLE `mkt_export_batch` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `batch_no` varchar(50) NOT NULL COMMENT '导出批次号',
  `export_type` varchar(30) NOT NULL DEFAULT 'excel' COMMENT '导出类型 excel/feishu',
  `source_type` varchar(50) NOT NULL COMMENT '来源类型',
  `item_count` int unsigned NOT NULL DEFAULT '0' COMMENT '导出数量',
  `file_url` varchar(1000) DEFAULT NULL COMMENT '导出文件地址',
  `feishu_table_id` varchar(100) DEFAULT NULL COMMENT '飞书多维表格ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1处理中 2成功 3失败',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
