-- ----------------------------
-- Table structure for mkt_member_quota_log
-- ----------------------------
DROP TABLE IF EXISTS `mkt_member_quota_log`;
CREATE TABLE `mkt_member_quota_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `quota_type` varchar(50) NOT NULL COMMENT '额度类型 generation内容 image图片',
  `quota_bucket` varchar(50) NOT NULL DEFAULT 'member_monthly' COMMENT '额度来源 member_monthly/purchased/manual',
  `change_type` varchar(50) NOT NULL COMMENT '变更类型 reset/manual_add/consume/refund',
  `change_value` int NOT NULL DEFAULT '0' COMMENT '变更值',
  `before_value` int NOT NULL DEFAULT '0' COMMENT '变更前剩余额度',
  `after_value` int NOT NULL DEFAULT '0' COMMENT '变更后剩余额度',
  `biz_type` varchar(50) DEFAULT NULL COMMENT '业务类型',
  `biz_id` varchar(64) DEFAULT NULL COMMENT '业务ID',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`),
  KEY `idx_quota_type` (`quota_type`),
  KEY `idx_change_type` (`change_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='会员额度流水表';

