-- ----------------------------
-- Table structure for mkt_prompt_template
-- ----------------------------
DROP TABLE IF EXISTS `mkt_prompt_template`;
CREATE TABLE `mkt_prompt_template` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(100) NOT NULL COMMENT '模板名称',
  `code` varchar(80) NOT NULL COMMENT '模板编码',
  `type` varchar(50) NOT NULL COMMENT '模板类型',
  `scene` varchar(50) NOT NULL DEFAULT 'text_content' COMMENT '使用场景',
  `description` varchar(500) DEFAULT NULL COMMENT '模板说明',
  `system_prompt` text COMMENT '系统提示词',
  `prompt_text` mediumtext NOT NULL COMMENT '用户提示词模板',
  `input_schema_json` json DEFAULT NULL COMMENT '动态表单配置JSON',
  `example_input_json` json DEFAULT NULL COMMENT '示例输入JSON',
  `example_output` mediumtext COMMENT '示例输出',
  `ai_config_id` int unsigned DEFAULT NULL COMMENT '默认AI配置ID',
  `temperature` decimal(3,2) NOT NULL DEFAULT '0.70' COMMENT '温度',
  `sort` int NOT NULL DEFAULT '100' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1正常 2停用',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_type` (`type`),
  KEY `idx_scene` (`scene`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='预设提示词表';

-- ----------------------------
-- Records of mkt_prompt_template
-- ----------------------------
BEGIN;
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (1, '小红书笔记生成', 'xhs_note_default', 'xhs_note', 'xhs_note', '根据主题、卖点和人群生成一篇小红书种草笔记', '你是资深小红书内容营销编辑，擅长把产品信息写成自然、有画面感、不过度夸张的中文种草内容。输出要包含标题、正文、标签，避免承诺疗效和绝对化用语。', '请生成一篇小红书笔记。主题：{{topic}}。目标人群：{{audience}}。核心卖点：{{selling_points}}。语气风格：{{tone}}。期望字数：{{word_count}}。请输出：1. 3个标题候选；2. 一篇完整正文；3. 8-12个话题标签；4. 适合封面的短句。', '[{\"key\": \"topic\", \"type\": \"input\", \"label\": \"主题\", \"required\": true, \"placeholder\": \"例如：春夏通勤防晒好物\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：25-35岁通勤女生\"}, {\"key\": \"selling_points\", \"type\": \"textarea\", \"label\": \"核心卖点\", \"required\": true, \"placeholder\": \"每行一个卖点\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"语气风格\", \"options\": [\"自然真实\", \"专业测评\", \"轻松种草\", \"干货清单\"], \"required\": true}, {\"key\": \"word_count\", \"type\": \"input\", \"label\": \"期望字数\", \"required\": true, \"placeholder\": \"例如：500\"}]', '{\"tone\": \"自然真实\", \"topic\": \"春夏通勤防晒好物\", \"audience\": \"25-35岁通勤女生\", \"word_count\": \"500\", \"selling_points\": \"清爽不黏腻；成膜快；适合补涂\"}', '标题候选、正文、标签和封面短句', NULL, 0.75, 10, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (2, '小红书标题生成', 'xhs_title_default', 'title', 'title', '为笔记主题或正文生成小红书标题候选', '你是小红书标题优化助手，擅长生成自然、有点击欲望但不标题党的中文标题。', '请根据以下信息生成{{count}}个小红书标题。主题：{{topic}}。内容摘要：{{content_summary}}。要求：标题口语化、具体、有场景感，避免夸张承诺。', '[{\"key\": \"topic\", \"type\": \"input\", \"label\": \"主题\", \"required\": true, \"placeholder\": \"例如：周末露营穿搭\"}, {\"key\": \"content_summary\", \"type\": \"textarea\", \"label\": \"内容摘要\", \"required\": true, \"placeholder\": \"输入笔记大意或卖点\"}, {\"key\": \"count\", \"type\": \"input\", \"label\": \"标题数量\", \"required\": true, \"placeholder\": \"例如：10\"}]', '{\"count\": \"10\", \"topic\": \"周末露营穿搭\", \"content_summary\": \"轻便、防晒、适合拍照\"}', '10个标题候选', NULL, 0.80, 20, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (3, '话题标签生成', 'xhs_tags_default', 'tags', 'tags', '根据正文和关键词生成小红书话题标签', '你是小红书话题标签助手，擅长生成相关、克制、不堆砌的中文标签。', '请根据正文和关键词生成12个以内小红书话题标签。关键词：{{keyword}}。正文：{{content}}。请只输出标签列表，并优先覆盖核心品类、场景、人群和风格。', '[{\"key\": \"keyword\", \"type\": \"input\", \"label\": \"关键词\", \"required\": false, \"placeholder\": \"例如：防晒、通勤\"}, {\"key\": \"content\", \"type\": \"textarea\", \"label\": \"正文\", \"required\": true, \"placeholder\": \"粘贴正文内容\"}]', '{\"content\": \"一段小红书正文\", \"keyword\": \"防晒、通勤\"}', '#防晒 #通勤穿搭 #好物分享', NULL, 0.65, 30, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (4, '正文改写优化', 'xhs_rewrite_default', 'rewrite', 'rewrite', '优化已有正文表达，保持原意但提升结构和种草感', '你是中文内容改写助手。请保留原意，优化表达、结构和节奏，避免机械堆词和夸张宣传。', '请改写以下内容。原文：{{original_content}}。改写目标：{{rewrite_goal}}。语气风格：{{tone}}。请输出改写后的正文，并列出3条优化说明。', '[{\"key\": \"original_content\", \"type\": \"textarea\", \"label\": \"原文\", \"required\": true, \"placeholder\": \"粘贴需要改写的内容\"}, {\"key\": \"rewrite_goal\", \"type\": \"input\", \"label\": \"改写目标\", \"required\": true, \"placeholder\": \"例如：更自然、更像真实体验\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"语气风格\", \"options\": [\"自然真实\", \"更精简\", \"更有干货\", \"更有种草感\"], \"required\": true}]', '{\"tone\": \"自然真实\", \"rewrite_goal\": \"更自然\", \"original_content\": \"原始正文\"}', '改写正文和优化说明', NULL, 0.70, 40, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (5, '爆文仿写', 'xhs_hot_rewrite_default', 'hot_rewrite', 'hot_rewrite', '参考爆文结构，为自己的产品或主题生成新笔记', '你是小红书爆文结构拆解和仿写助手。请学习结构、节奏和表达方式，不要复制原文句子。', '请参考爆文内容，生成一篇新的小红书笔记。爆文：{{hot_post}}。新主题或产品：{{product_name}}。核心卖点：{{selling_points}}。目标人群：{{audience}}。请先拆解爆文结构，再输出新笔记正文、标题和标签。', '[{\"key\": \"hot_post\", \"type\": \"textarea\", \"label\": \"爆文内容\", \"required\": true, \"placeholder\": \"粘贴参考爆文\"}, {\"key\": \"product_name\", \"type\": \"input\", \"label\": \"新主题/产品\", \"required\": true, \"placeholder\": \"例如：轻食代餐杯\"}, {\"key\": \"selling_points\", \"type\": \"textarea\", \"label\": \"核心卖点\", \"required\": true, \"placeholder\": \"每行一个卖点\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：健身新手\"}]', '{\"audience\": \"健身新手\", \"hot_post\": \"参考爆文\", \"product_name\": \"轻食代餐杯\", \"selling_points\": \"高蛋白；低负担；方便携带\"}', '结构拆解和仿写正文', NULL, 0.78, 50, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (6, '图片提示词生成', 'xhs_image_prompt_default', 'image_prompt', 'image_prompt', '根据笔记内容生成适合图片模型的中文图片提示词', '你是内容营销图片提示词助手，擅长把运营需求转成清晰、可执行的图片生成提示词。', '请根据以下内容生成一段图片生成提示词。笔记内容：{{content}}。画面风格：{{style}}。场景细节：{{scene_detail}}。请输出：主体、场景、构图、光线、色彩、质感、负面约束。', '[{\"key\": \"content\", \"type\": \"textarea\", \"label\": \"笔记内容\", \"required\": true, \"placeholder\": \"粘贴笔记正文或产品信息\"}, {\"key\": \"style\", \"type\": \"select\", \"label\": \"画面风格\", \"options\": [\"干净通透\", \"生活方式\", \"产品静物\", \"杂志感\", \"真实手机拍摄\"], \"required\": true}, {\"key\": \"scene_detail\", \"type\": \"textarea\", \"label\": \"场景细节\", \"required\": false, \"placeholder\": \"例如：咖啡桌、自然光、通勤包\"}]', '{\"style\": \"生活方式\", \"content\": \"防晒产品笔记\", \"scene_detail\": \"咖啡桌、自然光、通勤包\"}', '一段可直接给图片模型使用的提示词', NULL, 0.72, 60, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (7, '图片生成', 'xhs_image_generate_default', 'image_generate', 'image', '调用图片模型生成内容营销配图', '你是适合小红书内容营销场景的图片生成助手。请根据用户提示生成清晰、干净、商业友好的图片结果。', '{{image_prompt}}。图片比例：{{aspect_ratio}}。要求画面干净、主体明确、无多余文字、适合小红书封面或正文配图。', '[{\"key\": \"image_prompt\", \"type\": \"textarea\", \"label\": \"图片提示词\", \"required\": true, \"placeholder\": \"输入图片生成提示词\"}, {\"key\": \"aspect_ratio\", \"type\": \"select\", \"label\": \"图片比例\", \"options\": [\"1:1\", \"3:4\", \"4:5\", \"16:9\"], \"required\": true}]', '{\"aspect_ratio\": \"4:5\", \"image_prompt\": \"一张干净通透的防晒产品生活方式图\"}', '图片模型返回结果', NULL, 0.70, 70, 1, '系统预设模板', 1, NULL, '2026-05-26 19:26:05', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (8, '产品种草图文笔记', 'xhs_product_seeding_default', 'product_seeding', 'xhs_note', '根据产品信息、图片描述和卖点生成小红书种草笔记', '你是资深小红书内容营销编辑。请把产品信息写成自然真实的图文种草笔记，避免夸大承诺、疗效表述和绝对化用语。输出要适合普通用户直接二次编辑。', '请为以下产品生成一篇小红书图文笔记。产品名称：{{product_name}}。产品信息/图片描述：{{product_info}}。目标人群：{{audience}}。核心卖点：{{selling_points}}。语气风格：{{tone}}。期望字数：{{word_count}}。请输出：1. 3个标题候选；2. 完整正文；3. 图片拍摄/生成建议；4. 8-12个话题标签；5. 封面短句。', '[{\"key\": \"product_name\", \"type\": \"input\", \"label\": \"产品名称\", \"required\": true, \"placeholder\": \"例如：轻薄通勤防晒衣\"}, {\"key\": \"product_info\", \"type\": \"textarea\", \"label\": \"产品信息\", \"required\": true, \"placeholder\": \"填写产品图片描述、规格、使用场景、素材信息\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：25-35岁通勤女生\"}, {\"key\": \"selling_points\", \"type\": \"textarea\", \"label\": \"核心卖点\", \"required\": true, \"placeholder\": \"每行一个卖点\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"语气风格\", \"options\": [\"自然真实\", \"专业测评\", \"轻松种草\", \"干货清单\"], \"required\": true}, {\"key\": \"word_count\", \"type\": \"input\", \"label\": \"期望字数\", \"required\": true, \"placeholder\": \"例如：500\"}]', '{\"tone\": \"自然真实\", \"audience\": \"25-35岁通勤女生\", \"word_count\": \"500\", \"product_info\": \"白色短款，适合通勤和周末户外，面料轻薄\", \"product_name\": \"轻薄通勤防晒衣\", \"selling_points\": \"轻薄不闷；好搭配；适合通勤和旅行\"}', '标题候选、正文、图片建议、标签和封面短句', NULL, 0.75, 12, 1, '系统预设模板', 1, NULL, '2026-05-26 19:51:08', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (9, '灵感创作笔记', 'xhs_creative_inspiration_default', 'creative_inspiration', 'xhs_note', '根据创意想法生成内容方向、图片提示和小红书笔记草稿', '你是小红书创意策划和内容编辑，擅长把一个模糊想法拆成可执行的选题、画面和笔记。表达要具体、有场景感，避免空泛鸡汤。', '请基于创意想法生成小红书内容方案。创意想法：{{creative_idea}}。目标人群：{{audience}}。使用场景：{{scene_detail}}。内容风格：{{content_style}}。请输出：1. 5个选题方向；2. 推荐的主选题；3. 完整笔记正文；4. 图片生成/拍摄提示词；5. 话题标签。', '[{\"key\": \"creative_idea\", \"type\": \"textarea\", \"label\": \"创意想法\", \"required\": true, \"placeholder\": \"例如：把夏天通勤包里的防晒好物做成清单\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：刚入职的职场新人\"}, {\"key\": \"scene_detail\", \"type\": \"textarea\", \"label\": \"使用场景\", \"required\": false, \"placeholder\": \"例如：通勤路上、办公室补涂、周末短途\"}, {\"key\": \"content_style\", \"type\": \"select\", \"label\": \"内容风格\", \"options\": [\"季节限定\", \"节日营销\", \"新品上市\", \"用户痛点\", \"真实体验\"], \"required\": true}]', '{\"audience\": \"刚入职的职场新人\", \"scene_detail\": \"通勤路上、办公室补涂、周末短途\", \"content_style\": \"季节限定\", \"creative_idea\": \"夏天通勤包里的防晒好物清单\"}', '选题方向、正文、图片提示词和标签', NULL, 0.82, 14, 1, '系统预设模板', 1, NULL, '2026-05-26 19:51:08', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (10, '批量爆款改写', 'xhs_batch_viral_rewrite_default', 'batch_viral_rewrite', 'hot_rewrite', '批量粘贴爆款内容或链接，生成可落地的改写方案', '你是小红书爆文拆解和批量改写助手。请只学习结构、选题角度和表达节奏，不复制原文句子。输出要清晰分组，方便运营逐条使用。', '请批量处理以下爆款素材。素材或链接列表：{{hot_materials}}。新主题/产品：{{product_name}}。目标人群：{{audience}}。改写目标：{{rewrite_goal}}。每条输出数量：{{count_per_item}}。请对每条素材输出：结构拆解、可复用角度、改写后的标题候选、正文草稿、标签。', '[{\"key\": \"hot_materials\", \"type\": \"textarea\", \"label\": \"爆款素材\", \"required\": true, \"placeholder\": \"每行一条爆文内容或笔记链接，建议不超过10条\"}, {\"key\": \"product_name\", \"type\": \"input\", \"label\": \"新主题/产品\", \"required\": true, \"placeholder\": \"例如：轻食代餐杯\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：健身新手\"}, {\"key\": \"rewrite_goal\", \"type\": \"input\", \"label\": \"改写目标\", \"required\": true, \"placeholder\": \"例如：更自然、更适合种草转化\"}, {\"key\": \"count_per_item\", \"type\": \"select\", \"label\": \"每条数量\", \"options\": [\"1\", \"2\", \"3\"], \"required\": true}]', '{\"audience\": \"健身新手\", \"product_name\": \"轻食代餐杯\", \"rewrite_goal\": \"更自然、更适合种草转化\", \"hot_materials\": \"爆文链接或正文1\\n爆文链接或正文2\", \"count_per_item\": \"1\"}', '按素材分组的结构拆解和改写内容', NULL, 0.78, 55, 1, '系统预设模板', 1, NULL, '2026-05-26 19:51:08', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (11, '小红书攻略帖文字生成', 'xhs_guide_post_text_default', 'guide_text', 'guide_post', '生成餐饮门店、品类或消费攻略类小红书文案', '你是餐饮类小红书攻略帖编辑，擅长把门店信息、消费场景和用户痛点写成可收藏、可决策的攻略内容。避免夸张承诺和虚假体验。', '请生成一篇小红书攻略帖。攻略主题：{{topic}}。门店/品类信息：{{store_info}}。目标人群：{{audience}}。推荐理由：{{recommend_reasons}}。避坑提醒：{{tips}}。语气风格：{{tone}}。请输出：标题候选、正文、清单结构、话题标签、封面短句。', '[{\"key\": \"topic\", \"type\": \"input\", \"label\": \"攻略主题\", \"required\": true, \"placeholder\": \"例如：周末朋友聚餐餐厅攻略\"}, {\"key\": \"store_info\", \"type\": \"textarea\", \"label\": \"门店/品类信息\", \"required\": true, \"placeholder\": \"填写门店、菜品、位置、价格、人均等信息\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"目标人群\", \"required\": true, \"placeholder\": \"例如：情侣约会、朋友聚餐、亲子家庭\"}, {\"key\": \"recommend_reasons\", \"type\": \"textarea\", \"label\": \"推荐理由\", \"required\": true, \"placeholder\": \"每行一个推荐理由\"}, {\"key\": \"tips\", \"type\": \"textarea\", \"label\": \"避坑提醒\", \"required\": false, \"placeholder\": \"例如：高峰期排队、停车、预约\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"语气风格\", \"options\": [\"真实体验\", \"攻略清单\", \"朋友安利\", \"专业测评\"], \"required\": true}]', '{\"tips\": \"饭点建议提前排队\", \"tone\": \"攻略清单\", \"topic\": \"周末朋友聚餐餐厅攻略\", \"audience\": \"朋友聚餐\", \"store_info\": \"商场内新开的湘菜馆，人均80，招牌小炒黄牛肉\", \"recommend_reasons\": \"上菜快；环境明亮；菜品下饭\"}', '攻略帖标题、正文、标签和封面短句', NULL, 0.76, 11, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (12, '小红书攻略帖生图', 'xhs_guide_post_image_default', 'guide_image', 'image', '为攻略帖生成2-5张小红书配图', '你是餐饮小红书配图生成助手，擅长生成真实、干净、适合攻略帖排版的图片提示词。', '{{guide_content}}。生成{{image_count}}张小红书攻略帖配图，模板风格：{{template_style}}，图片比例：{{aspect_ratio}}。要求主体明确、光线自然、餐饮场景真实、有攻略帖封面感。', '[{\"key\": \"guide_content\", \"type\": \"textarea\", \"label\": \"攻略内容\", \"required\": true, \"placeholder\": \"粘贴攻略帖正文或门店信息\"}, {\"key\": \"template_style\", \"type\": \"select\", \"label\": \"模板风格\", \"options\": [\"自由生成\", \"清单封面\", \"探店实拍\", \"菜品特写\", \"门店氛围\"], \"required\": true}, {\"key\": \"image_count\", \"type\": \"select\", \"label\": \"图片数量\", \"options\": [\"2\", \"3\", \"4\", \"5\"], \"required\": true}, {\"key\": \"aspect_ratio\", \"type\": \"select\", \"label\": \"图片比例\", \"options\": [\"1:1\", \"3:4\", \"4:5\"], \"required\": true}]', '{\"image_count\": \"3\", \"aspect_ratio\": \"4:5\", \"guide_content\": \"一篇餐饮攻略帖正文\", \"template_style\": \"清单封面\"}', '图片生成结果', NULL, 0.70, 12, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (13, '小红书攻略帖批量生成', 'xhs_guide_post_batch_default', 'guide_batch', 'guide_post', '批量生成多条餐饮攻略帖草稿', '你是餐饮小红书批量内容编辑，请把批量主题拆成多条可发布草稿，每条都要避免重复表达。', '请根据以下批量主题生成小红书攻略帖。批量主题：{{topics}}。统一人群：{{audience}}。统一风格：{{tone}}。每条输出标题、正文、标签和封面短句。', '[{\"key\": \"topics\", \"type\": \"textarea\", \"label\": \"批量主题\", \"required\": true, \"placeholder\": \"每行一个主题或门店信息\"}, {\"key\": \"audience\", \"type\": \"input\", \"label\": \"统一人群\", \"required\": true, \"placeholder\": \"例如：周末聚餐用户\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"统一风格\", \"options\": [\"攻略清单\", \"朋友安利\", \"真实体验\"], \"required\": true}]', '{\"tone\": \"攻略清单\", \"topics\": \"湘菜聚餐攻略\\n火锅避坑攻略\", \"audience\": \"周末聚餐用户\"}', '多条攻略帖草稿', NULL, 0.78, 13, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (14, 'AI生成求推荐帖', 'xhs_recommend_post_default', 'recommend_post', 'recommend_post', '根据客户提示词生成纯文字求推荐帖', '你是小红书求推荐帖文案助手。必须严格输出可被 JSON.parse 解析的 JSON 对象，只允许包含 title 和 content 两个字符串字段，不要输出 Markdown、代码块、解释文字或标题候选列表。', '请生成一条小红书求推荐帖。需求：{{request_detail}}。城市/商圈：{{location}}。预算：{{budget}}。口吻：{{tone}}。\n\n必须只输出一个合法 JSON 对象，不要输出 Markdown、代码块、解释文字或多余前后缀。\nJSON 结构必须完全如下：\n{\n  \"title\": \"一条最适合直接展示的中文标题，30字以内，不要包含标题候选、正文等字段名\",\n  \"content\": \"一条完整的小红书求推荐正文，口语化、真实、有求助感，正文里不要包含标题候选列表\"\n}\n\n字段要求：\n1. title 只能是一条标题，不能是数组，不能写“标题候选：”。\n2. content 只能是正文，不能混入标题候选、JSON 以外说明或平台无关内容。\n3. JSON 字符串内如需换行请使用 \\n。', '[{\"key\": \"request_detail\", \"type\": \"textarea\", \"label\": \"推荐需求\", \"required\": true, \"placeholder\": \"例如：想找适合朋友生日聚餐的餐厅\"}, {\"key\": \"location\", \"type\": \"input\", \"label\": \"城市/商圈\", \"required\": false, \"placeholder\": \"例如：龙湖区黄山路71号附近\"}, {\"key\": \"budget\", \"type\": \"input\", \"label\": \"预算\", \"required\": false, \"placeholder\": \"例如：人均150以内\"}, {\"key\": \"tone\", \"type\": \"select\", \"label\": \"口吻\", \"options\": [\"真实求助\", \"轻松口语\", \"急求推荐\", \"姐妹求助\", \"本地人求助\", \"避雷求推荐\", \"生日聚餐求助\", \"约会探店求助\", \"家庭聚餐求助\", \"外地游客求助\"], \"required\": true}]', '[{\"tone\": \"生日聚餐求助\", \"budget\": \"人均150以内\", \"location\": \"龙湖区黄山路71号正迪科技大厦一楼附近，距离星湖商业城步行1.3km\", \"request_detail\": \"想找适合朋友生日聚餐的餐厅，环境不要太吵，菜品稳定一点，适合拍照聊天\"}, {\"tone\": \"约会探店求助\", \"budget\": \"人均120-180\", \"location\": \"汕头龙湖区星湖城附近\", \"request_detail\": \"想找适合两个人约会吃饭的火锅或潮汕菜，最好不要排队太久，环境舒服一点\"}, {\"tone\": \"外地游客求助\", \"budget\": \"人均100-160\", \"location\": \"汕头市区，龙湖区或金平区都可以\", \"request_detail\": \"外地朋友第一次来，想带他们吃有本地特色的餐厅，最好有招牌菜、不踩雷\"}, {\"tone\": \"真实求助\", \"budget\": \"人均150以内\", \"location\": \"贵阳南明区火花园双子塔附近\", \"request_detail\": \"公司小聚餐，8个人左右，想找能坐久一点、服务别催、适合聊天的店\"}, {\"tone\": \"家庭聚餐求助\", \"budget\": \"人均100-150\", \"location\": \"贵阳观山湖区会展城附近\", \"request_detail\": \"家里长辈一起吃饭，想找口味稳、环境干净、停车方便的餐厅\"}, {\"tone\": \"避雷求推荐\", \"budget\": \"人均150左右\", \"location\": \"汕头龙湖区\", \"request_detail\": \"最近刷到很多卤水火锅，不知道哪家真的好吃，想求真实体验和必点菜\"}]', '纯文字求推荐帖', NULL, 0.75, 30, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (15, '美团差评申诉分析', 'meituan_review_appeal_default', 'review_appeal', 'appeal', '分析美团差评并生成申诉建议', '你是本地生活平台差评申诉顾问。请基于用户提供的差评内容和证据，给出合规、克制、可执行的申诉策略。', '平台：美团。差评文字：{{review_text}}。图片/证据描述：{{evidence_desc}}。商家说明：{{merchant_context}}。请输出：差评问题拆解、可申诉点、补充证据建议、申诉文案。', '[{\"key\": \"review_text\", \"type\": \"textarea\", \"label\": \"差评文字\", \"required\": true, \"placeholder\": \"粘贴差评内容\"}, {\"key\": \"evidence_desc\", \"type\": \"textarea\", \"label\": \"图片/证据描述\", \"required\": false, \"placeholder\": \"描述上传图片、订单、监控、沟通记录等\"}, {\"key\": \"merchant_context\", \"type\": \"textarea\", \"label\": \"商家说明\", \"required\": false, \"placeholder\": \"填写商家认为不实或需解释的背景\"}]', '{\"review_text\": \"顾客差评文字\", \"evidence_desc\": \"订单截图、沟通记录\", \"merchant_context\": \"顾客实际未到店\"}', '申诉分析和申诉文案', NULL, 0.62, 40, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (16, '大众点评差评申诉分析', 'dianping_review_appeal_default', 'review_appeal', 'appeal', '分析大众点评差评并生成申诉建议', '你是本地生活平台差评申诉顾问。请基于用户提供的差评内容和证据，给出合规、克制、可执行的申诉策略。', '平台：大众点评。差评文字：{{review_text}}。图片/证据描述：{{evidence_desc}}。商家说明：{{merchant_context}}。请输出：差评问题拆解、可申诉点、补充证据建议、申诉文案。', '[{\"key\": \"review_text\", \"type\": \"textarea\", \"label\": \"差评文字\", \"required\": true, \"placeholder\": \"粘贴差评内容\"}, {\"key\": \"evidence_desc\", \"type\": \"textarea\", \"label\": \"图片/证据描述\", \"required\": false, \"placeholder\": \"描述上传图片、订单、监控、沟通记录等\"}, {\"key\": \"merchant_context\", \"type\": \"textarea\", \"label\": \"商家说明\", \"required\": false, \"placeholder\": \"填写商家认为不实或需解释的背景\"}]', '{\"review_text\": \"顾客差评文字\", \"evidence_desc\": \"订单截图、沟通记录\", \"merchant_context\": \"顾客实际未到店\"}', '申诉分析和申诉文案', NULL, 0.62, 41, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (17, 'GPT Image2自由生图', 'gpt_image2_free_default', 'gpt_image2', 'image', '自由输入提示词调用GPT Image2生成图片', '你是GPT Image2营销图片生成助手，请生成商业友好、主体明确、适合本地生活商家的图片。', '{{prompt}}。图片数量：{{image_count}}。图片比例：{{aspect_ratio}}。风格：{{style}}。要求画面干净、主体突出、适合社媒传播。', '[{\"key\": \"prompt\", \"type\": \"textarea\", \"label\": \"提示词\", \"required\": true, \"placeholder\": \"输入图片生成需求\"}, {\"key\": \"image_count\", \"type\": \"select\", \"label\": \"图片数量\", \"options\": [\"1\", \"2\", \"3\", \"4\", \"5\"], \"required\": true}, {\"key\": \"aspect_ratio\", \"type\": \"select\", \"label\": \"图片比例\", \"options\": [\"1:1\", \"3:4\", \"4:5\", \"16:9\"], \"required\": true}, {\"key\": \"style\", \"type\": \"select\", \"label\": \"风格\", \"options\": [\"写实\", \"产品广告\", \"餐饮海报\", \"极简\", \"轻奢\"], \"required\": true}]', '{\"style\": \"餐饮海报\", \"prompt\": \"一张适合火锅店上新的营销图片\", \"image_count\": \"2\", \"aspect_ratio\": \"4:5\"}', '图片生成结果', NULL, 0.70, 50, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
INSERT INTO `mkt_prompt_template` (`id`, `name`, `code`, `type`, `scene`, `description`, `system_prompt`, `prompt_text`, `input_schema_json`, `example_input_json`, `example_output`, `ai_config_id`, `temperature`, `sort`, `status`, `remark`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (18, 'GPT Image2模板改图', 'gpt_image2_template_edit_default', 'gpt_image2_edit', 'image', '根据模板库样式和提示词一键改图', '你是GPT Image2模板改图助手，请保留模板风格，结合用户提示词改造成新的营销图片。', '参考模板：{{template_name}}。改图需求：{{edit_prompt}}。参考图/素材说明：{{reference_desc}}。图片数量：{{image_count}}。要求保持模板风格一致，内容替换自然。', '[{\"key\": \"template_name\", \"type\": \"input\", \"label\": \"模板名称\", \"required\": true, \"placeholder\": \"例如：餐饮新品海报模板\"}, {\"key\": \"edit_prompt\", \"type\": \"textarea\", \"label\": \"改图需求\", \"required\": true, \"placeholder\": \"描述需要替换的主体、文字或风格\"}, {\"key\": \"reference_desc\", \"type\": \"textarea\", \"label\": \"参考素材说明\", \"required\": false, \"placeholder\": \"描述参考图、产品图或门店图\"}, {\"key\": \"image_count\", \"type\": \"select\", \"label\": \"图片数量\", \"options\": [\"1\", \"2\", \"3\", \"4\", \"5\"], \"required\": true}]', '{\"edit_prompt\": \"替换成酸汤火锅新品\", \"image_count\": \"2\", \"template_name\": \"餐饮新品海报模板\", \"reference_desc\": \"红色汤底、金属锅具、热气\"}', '模板改图结果', NULL, 0.68, 51, 1, '客户需求预设模板', 1, NULL, '2026-05-26 20:03:03', NULL, NULL);
COMMIT;

-- ----------------------------
-- Table structure for mkt_recommend_post
-- ----------------------------
DROP TABLE IF EXISTS `mkt_recommend_post`;
CREATE TABLE `mkt_recommend_post` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `task_no` varchar(50) DEFAULT NULL COMMENT 'AI任务编号',
  `title` varchar(200) NOT NULL COMMENT '求推荐标题',
  `content` mediumtext COMMENT '求推荐文案',
  `qrcode_token` varchar(80) DEFAULT NULL COMMENT '二维码Token',
  `redirect_url` varchar(1000) DEFAULT NULL COMMENT '跳转地址',
  `copy_count` int unsigned NOT NULL DEFAULT '0' COMMENT '复制次数',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1正常 2停用',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_qrcode_token` (`qrcode_token`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='AI求推荐帖库';

-- ----------------------------
-- Records of mkt_recommend_post
-- ----------------------------
BEGIN;
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (1, 111, 'AIT20260527121143365898', '龙湖区朋友生日聚餐求推荐！人均150内🙏', '姐妹们求助一下！！\n\n朋友快生日了，想找一家适合聚餐的餐厅，位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/打车方便一点就行。\n\n预算希望控制在人均150以内，不想太贵，但也想吃得有点特色，环境不要太吵，适合朋友一起聊天拍照，最好菜品稳定一点，不踩雷。\n\n我们几个都比较能接受火锅、潮汕菜、卤味这类，最近有刷到卤水火锅，好像有非遗卤水锅底、狮头鹅、鲜切牛肉、卤味拼盘这些，感觉还挺适合外地朋友体验潮汕味道的，但不知道生日聚餐氛围怎么样。\n\n有没有本地姐妹吃过附近的店？  \n求推荐适合生日聚餐、服务和出品都还不错的餐厅！最好能说说人均、必点菜、需不需要提前订位～谢谢大家！！', '381640268022a69f6ef89bf9', NULL, 5, 1, 111, 111, '2026-05-27 12:11:57', '2026-05-27 12:47:06', NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (2, 112, 'AIT20260527122916725499', '贵阳南明区求推荐！朋友生日聚餐去哪吃？', '贵阳南明区火花园双子塔附近有没有适合朋友生日聚餐的餐厅推荐呀？\n\n预算想控制在人均150以内，最好是氛围轻松一点、适合一群朋友边吃边聊的那种，不想太正式，但也希望菜品别踩雷。\n\n我们大概几个人一起，想找那种位置方便、吃完不会太尴尬冷场的店，火锅、牛肉锅、卤味锅或者贵州本地特色都可以，重点是好吃、适合庆生、性价比在线。\n\n如果店里环境适合拍照、服务不催人、能坐久一点就更好了！  \n有没有本地朋友或者来这附近吃过的姐妹推荐一下？求真实体验，别让我生日局翻车🙏', 'eed071b938420971744862b4', NULL, 9, 1, 112, NULL, '2026-05-27 12:29:23', '2026-05-27 12:46:29', NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (3, 111, 'AIT20260527125220414277', '龙湖区约会火锅求推荐！', '想问问汕头本地朋友～龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城步行能到的范围，有没有适合两个人约会吃饭的火锅/潮汕菜推荐呀？\n\n预算大概人均120-180，希望环境舒服一点、聊天不吵，最好不要排队太久。我们比较想吃有潮汕特色的，比如卤水火锅、鲜切牛肉、卤味拼盘、粿条海鲜这些都可以。\n\n看到附近有家潮卤道非遗卤水火锅，好像是卤水锅底和狮头鹅比较有特色，不知道适不适合情侣约会？味道、环境、等位情况怎么样？\n\n如果还有附近好吃不踩雷的店也求推荐！适合晚上去、两个人点菜不尴尬的那种～', '6cb4a515c9b5c82f24a6fc3b', NULL, 0, 1, 111, NULL, '2026-05-27 12:52:30', NULL, NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (4, 111, 'AIT20260527125304798243', '外地朋友来龙湖区吃啥不踩雷', '外地朋友第一次来汕头，想带他们吃一顿比较有本地特色的餐厅，求大家推荐🙏\n我们大概在龙湖区黄山路71号正迪科技大厦一楼附近，离星湖商业城步行大概1.3km，最好不要跑太远。\n预算人均100-160左右，想找那种有招牌菜、适合外地人体验潮汕味道、但又不会踩雷的店。\n目前看到附近有卤水火锅，说是有农家散养狮头鹅、非遗老卤锅底，还有鲜切牛肉、卤味拼盘、鹅血、粿条这些，感觉挺有特色的。想问问本地朋友这种适合带外地朋友去吗？\n主要诉求：环境别太乱、味道稳定、招牌菜值得点，最好能一顿吃到潮汕特色。大家有推荐的店或者必点菜吗？感谢！', '9aa6ce3b3dd4cf878d0b96b8', NULL, 0, 1, 111, NULL, '2026-05-27 12:53:14', NULL, NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (5, 111, 'AIT20260527125339136497', '带长辈吃饭求推荐！龙湖区附近', '周末想带家里长辈一起吃顿饭，想找一家口味比较稳、环境干净舒服、停车也方便的餐厅～\n\n位置最好在龙湖区黄山路71号正迪科技大厦一楼附近，或者星湖商业城周边也可以，步行/开车都别太折腾长辈。\n\n预算大概人均100-150，希望菜品别太踩雷，最好是适合一家人慢慢吃的那种。火锅、潮汕特色、卤味牛肉之类都可以，只要味道稳定、服务别太乱就行。\n\n有姐妹去过这附近比较适合家庭聚餐的店吗？求真实推荐，最好说说停车方不方便、长辈能不能吃得惯～', '1892e689999b9ef192f6c58f', NULL, 0, 1, 111, NULL, '2026-05-27 12:53:48', NULL, NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (6, 111, 'AIT20260527125956165358', '龙湖区卤水火锅求避雷推荐', '最近小红书一直刷到卤水火锅，看得我好心动但又有点怕踩雷😭\n\n想问问大家，龙湖区黄山路71号正迪科技大厦一楼这附近，距星湖商业城步行大概1.3km，有没有真的值得去的卤水火锅？人均预算150左右可以接受，主要想吃到卤香够、食材新鲜、不会齁咸的那种。\n\n特别想求真实体验：\n1️⃣ 卤水锅底会不会越煮越咸？\n2️⃣ 狮头鹅/卤味拼盘值不值得点？\n3️⃣ 鲜切牛肉配卤水锅底好吃吗？\n4️⃣ 鹅血、粿条、海鲜、时蔬这些有没有必点或避雷？\n5️⃣ 游客去吃会不会被坑，分量和服务怎么样？\n\n如果有去过潮汕卤水火锅的姐妹/本地朋友，求推荐靠谱店和必点菜！也欢迎直接劝退，想听真实感受🙏', '157bd84b18270ccc5f29e247', NULL, 0, 1, 111, NULL, '2026-05-27 13:00:07', NULL, NULL);
INSERT INTO `mkt_recommend_post` (`id`, `user_id`, `task_no`, `title`, `content`, `qrcode_token`, `redirect_url`, `copy_count`, `status`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (7, 111, 'AIT20260527130223501405', '带长辈在龙湖区吃饭求推荐', '周末想带家里长辈一起吃顿饭，求大家推荐一下龙湖区黄山路71号正迪科技大厦一楼附近的餐厅～最好离星湖商业城别太远，步行/开车都方便。\n\n预算大概人均100-150，主要想找口味比较稳、环境干净舒服、停车方便的店。长辈不太能接受太吵太重口，菜品最好有潮汕特色，像卤味、火锅、牛肉、粿条、时蔬这类都可以，吃起来踏实一点。\n\n有没有本地朋友吃过觉得适合家庭聚餐的？希望服务也不要太拉胯，座位宽敞一点更好。求真实推荐，感谢大家！', '315c8ed680157d5f266e2369', NULL, 0, 1, 111, NULL, '2026-05-27 13:02:32', NULL, NULL);
COMMIT;

-- ----------------------------
-- Table structure for mkt_review_analysis
-- ----------------------------
DROP TABLE IF EXISTS `mkt_review_analysis`;
CREATE TABLE `mkt_review_analysis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `task_no` varchar(50) DEFAULT NULL COMMENT 'AI任务编号',
  `platform` varchar(30) NOT NULL COMMENT '平台 meituan/dianping',
  `file_name` varchar(255) DEFAULT NULL COMMENT '上传文件名',
  `file_url` varchar(1000) DEFAULT NULL COMMENT '上传文件地址',
  `summary_image_url` varchar(1000) DEFAULT NULL COMMENT '长图总结地址',
  `analysis_text` longtext COMMENT '分析内容',
  `suggestion_text` longtext COMMENT '优化建议',
  `expires_at` datetime DEFAULT NULL COMMENT '过期清理时间',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1待分析 2成功 3失败',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_platform` (`user_id`,`platform`),
  KEY `idx_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='点评评价分析结果库';

-- ----------------------------
-- Records of mkt_review_analysis
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mkt_review_appeal
-- ----------------------------
DROP TABLE IF EXISTS `mkt_review_appeal`;
CREATE TABLE `mkt_review_appeal` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '系统用户ID',
  `platform` varchar(30) NOT NULL COMMENT '平台 meituan/dianping',
  `task_no` varchar(50) DEFAULT NULL COMMENT 'AI任务编号',
  `review_text` mediumtext COMMENT '差评文字',
  `image_urls_json` json DEFAULT NULL COMMENT '差评图片JSON',
  `analysis_text` mediumtext COMMENT 'AI分析',
  `appeal_text` mediumtext COMMENT '申诉文案',
  `evidence_suggestions` mediumtext COMMENT '举证建议',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 1待处理 2已分析 3失败',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_platform` (`user_id`,`platform`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='差评申诉分析记录';

-- ----------------------------
-- Records of mkt_review_appeal
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for mkt_user_ai_profile
-- ----------------------------
DROP TABLE IF EXISTS `mkt_user_ai_profile`;
CREATE TABLE `mkt_user_ai_profile` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '用户ID，关联sa_system_user.id',
  `industry` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '行业',
  `category` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品类',
  `sub_category` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '细分品类',
  `brand_name` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品牌名/账号名',
  `operation_area` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '经营区域',
  `target_customers` text COLLATE utf8mb4_general_ci COMMENT '目标客群',
  `core_selling_points` text COLLATE utf8mb4_general_ci COMMENT '核心卖点',
  `competitors` text COLLATE utf8mb4_general_ci COMMENT '竞品或参考账号',
  `extra_note` text COLLATE utf8mb4_general_ci COMMENT '补充说明',
  `created_by` int DEFAULT NULL COMMENT '创建人',
  `updated_by` int DEFAULT NULL COMMENT '更新人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_delete_time` (`delete_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='内容营销用户AI账号画像表';

