INSERT INTO `mkt_user_ai_profile` (`id`, `user_id`, `industry`, `category`, `sub_category`, `brand_name`, `operation_area`, `target_customers`, `core_selling_points`, `competitors`, `extra_note`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (2, 112, '餐饮', '火锅', '朋友聚餐', '贵州火锅', '贵州省贵阳市南明区火花园双子塔 L2-304', '游客、本地居民', '门店核心王牌，农家散养狮头鹅，非遗老卤慢卤，鹅肉紧实入味、卤香醇厚，潮汕非遗级食材，游客必打卡、非遗卤水锅底、潮汕鲜切牛肉：鲜切现涮，肉质鲜嫩，适配卤水锅底，解锁潮汕卤香 + 鲜牛肉双重风味、卤味拼盘、鹅血、粿条、海鲜、潮汕特色时蔬，一站式吃遍潮汕地道风味、人均111元', '潮皇叔牛肉火锅、围炉夜话、', '', 112, 112, '2026-05-27 12:27:48', '2026-05-27 12:29:08', NULL);
COMMIT;

-- ----------------------------
-- Table structure for mkt_user_membership
-- ----------------------------
DROP TABLE IF EXISTS `mkt_user_membership`;
CREATE TABLE `mkt_user_membership` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int unsigned NOT NULL COMMENT '关联系统用户ID',
  `level` varchar(50) NOT NULL DEFAULT 'free' COMMENT '会员等级',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '会员状态 1正常 2禁用 3过期',
  `expire_time` datetime DEFAULT NULL COMMENT '会员到期时间',
  `current_plan_id` int unsigned DEFAULT NULL COMMENT '当前套餐ID',
  `total_paid_amount` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '累计支付金额',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int DEFAULT NULL COMMENT '创建者',
  `updated_by` int DEFAULT NULL COMMENT '更新者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `delete_time` datetime DEFAULT NULL COMMENT '删除时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_level` (`level`),
  KEY `idx_status` (`status`),
  KEY `idx_expire_time` (`expire_time`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='用户会员扩展表';

