INSERT INTO `saiai_chat` (`id`, `group_id`, `user_id`, `role`, `model`, `content`, `tokens`, `ip`, `user_agent`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (2, 1, 1, 'assistant', 'generic', '> ✅ 绘图已完成\n\n![image](https://oss.filenest.top/uploads/bbf4ca7c-9c5f-4c6b-a0f6-6cd4093a787f.png)\n\n', 0, '', '', 1, 1, '2026-05-26 18:45:36', '2026-05-26 18:45:36', NULL);
INSERT INTO `saiai_chat` (`id`, `group_id`, `user_id`, `role`, `model`, `content`, `tokens`, `ip`, `user_agent`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (3, 2, 1, 'user', 'generic', 'hello', 0, '', '', 1, 1, '2026-05-26 18:46:10', '2026-05-26 18:46:10', NULL);
INSERT INTO `saiai_chat` (`id`, `group_id`, `user_id`, `role`, `model`, `content`, `tokens`, `ip`, `user_agent`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (4, 2, 1, 'assistant', 'generic', '> ✅ 绘图已完成\n\n![image](https://oss.filenest.top/uploads/2a33c7ad-c32e-49bb-ba07-ab87ab977c00.png)\n\n', 0, '', '', 1, 1, '2026-05-26 18:46:57', '2026-05-26 18:46:57', NULL);
INSERT INTO `saiai_chat` (`id`, `group_id`, `user_id`, `role`, `model`, `content`, `tokens`, `ip`, `user_agent`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (5, 3, 1, 'user', 'generic', '你好吖，今天发生了哪些热点新闻？', 0, '', '', 1, 1, '2026-05-26 18:48:32', '2026-05-26 18:48:32', NULL);
INSERT INTO `saiai_chat` (`id`, `group_id`, `user_id`, `role`, `model`, `content`, `tokens`, `ip`, `user_agent`, `created_by`, `updated_by`, `create_time`, `update_time`, `delete_time`) VALUES (6, 3, 1, 'assistant', 'generic', '今天（5月26日）全球和中文圈比较受关注的热点，主要集中在国际局势、科技、体育和社会新闻几个方向：\n\n### 国际热点\n- 美国与伊朗的谈判持续升温。美国国务卿 entity[\"politician\",\"Marco Rubio\",\"美国国务卿\"] 表示，美伊协议可能“还需要几天”，霍尔木兹海峡问题成为焦点之一。citeturn0news2turn0search17\n- 中东局势仍然紧张，以色列与黎巴嫩真主党冲突升级，以方表示将加大军事行动力度。citeturn0search17\n- 欧洲遭遇异常高温。法国、英国多地刷新5月高温纪录，部分赛事甚至出现跑者猝死事件，引发对极端气候的讨论。citeturn0news6\n\n### 中国与科技\n- 中国国际体育用品博览会在厦门举行，AI训练设备、智能运动器材、轻量化健身设备成为热点，国产体育科技受到关注。citeturn0news0\n- COMPUTEX 2026 台北电脑展持续刷屏，AI服务器、机器人、边缘计算等成为科技圈讨论重点，英特尔、英伟达相关消息热度很高。citeturn0search13\n- 中国官方继续推进防洪与生态治理，多地河流水位超警戒线。citeturn0search1turn0search17\n\n### 体育\n- 2026 世界杯门票抽签火爆，美国纽约地区开放的优惠票在3分钟内被抢空。citeturn0news10\n- NBA 东部决赛相关话题热度很高，entity[\"athlete\",\"Jalen Brunson\",\"NBA球员\"] 当选东决MVP成为微博和体育平台热门。citeturn0search7\n- 亚洲大型赛事相关筹备持续推进，包括 entity[\"sports_event\",\"2026 Asian Games\",\"爱知·名古屋亚运会\"] 和 entity[\"sports_event\",\"2026 Asian Beach Games\",\"三亚亚沙会\"]。citeturn0search22turn0search23\n\n### 娱乐与社交媒体热议\n- 第31届白玉兰奖入围名单公布，引发影视圈讨论。citeturn0search7\n- 关于 entity[\"people\",\"刘诗诗\",\"中国演员\"] 与 entity[\"people\",\"吴奇隆\",\"中国台湾演员\"] 的婚姻传闻再次登上娱乐热搜。citeturn0search5\n\n### 中文互联网热议话题\n- AI 是否正在改变传统职业与“师徒制”教育，引发媒体评论。citeturn0search3\n- “儿童牙膏”“手擀面”等消费概念营销再被点名，消费者维权与食品标签问题继续发酵。citeturn0search3\n\n如果你愿意，我还可以继续帮你整理：\n- 「今天微博/抖音热搜前十」\n- 「国际新闻深度版」\n- 「科技圈热点」\n- 「娱乐八卦版」\n- 「适合下班快速看的 5 分钟新闻摘要」', 0, '', '', 1, 1, '2026-05-26 18:48:54', '2026-05-26 18:48:54', NULL);
COMMIT;

